import {StringDecoder} from 'node:string_decoder';

// Only surface an authorization page generated by the official process during
// an active auth request. Never surface callbacks, tokens or general stderr.
export function googleAuthorizationUrl(value){
 if(typeof value!=='string'||value.length>32768)return null;
 try{const u=new URL(value);if(u.protocol!=='https:'||u.hostname!=='accounts.google.com'||u.port||u.username||u.password||!/^\/o\/oauth2\/(?:v2\/)?auth$/.test(u.pathname))return null;
  if(u.searchParams.get('response_type')!=='code'||!u.searchParams.get('client_id')||['access_token','refresh_token','id_token','code'].some(k=>u.searchParams.has(k)))return null;
  const callback=new URL(u.searchParams.get('redirect_uri'));if(callback.protocol!=='http:'||!['localhost','127.0.0.1','[::1]'].includes(callback.hostname)||callback.username||callback.password)return null;
  return u.href;
 }catch{return null;}
}
export function authOutputReader(onUrl){
 const decoder=new StringDecoder('utf8');let buffer='',seen=new Set();
 function line(text){for(const candidate of text.match(/https:\/\/accounts\.google\.com\/o\/oauth2\/(?:v2\/)?auth\?[^\s<>"']+/g)||[]){const url=googleAuthorizationUrl(candidate);if(url&&!seen.has(url)){seen.add(url);onUrl(url);}}}
 return {push(bytes){buffer+=decoder.write(bytes);let index;while((index=buffer.indexOf('\n'))>=0){line(buffer.slice(0,index));buffer=buffer.slice(index+1);}if(buffer.length>65536)buffer='';},flush(){buffer+=decoder.end();line(buffer);buffer='';}};
}
